// RelayControlServer is the server API for RelayControl service.
// All implementations must embed UnimplementedRelayControlServer
// for forward compatibility.
//
// 控制连接：选号、上游错误决策、额度、Key 查询等同步小消息（WP6、WP7、WP11）。
type RelayControlServer interface {
	Ping(context.Context, *PingRequest) (*PingResponse, error)
	// Heartbeat 心跳（设计 11.4）：每 5 秒一次，带本机的负载与计数；连续 15 秒收不到主节点把这台标为离线。
	// 回复带主节点时间（从节点据此测时钟偏差）。主节点按连接证书认定是哪台，不信报文里的任何节点标识。
	Heartbeat(context.Context, *HeartbeatRequest) (*HeartbeatResponse, error)
	// FetchConfig 拉取本节点的配置快照（启动、重连、纪元变化、版本落后时，设计 6.2）。
	FetchConfig(context.Context, *FetchConfigRequest) (*ConfigSnapshot, error)
	// ---- 额度（设计第 4 节）。申请随选号一起（WP7），这里是退回、续期、核对、收回确认。----
	// 这几个调用都动钱：必须带当前纪元，跨纪元一律拒绝（EPOCH_MISMATCH）；从节点先上报租约
	// （ReportLeases），再用同样的数值重发，不清零。
	// 退回类消息带"这份租约至今累计退回"而不是增量；主节点把累计记在租约上（持久化），只处理多出来的
	// 部分，重发、回复丢失、主节点重启后再发都只生效一次。
	ReleaseQuota(context.Context, *ReleaseQuotaRequest) (*ReleaseQuotaResponse, error)
	RenewLeases(context.Context, *RenewLeasesRequest) (*RenewLeasesResponse, error)
	// ReportLeases 重连或纪元变化后上报手里的租约：主节点关掉没上报的，告诉节点哪些已作废。
	// 上报完成之前从节点不发选号。
	ReportLeases(context.Context, *ReportLeasesRequest) (*ReportLeasesResponse, error)
	AckQuotaRecall(context.Context, *AckQuotaRecallRequest) (*AckQuotaRecallResponse, error)
	// ---- 准入与选号（设计 3.1 第 5 步、3.2，开发计划 WP7、WP9）----
	// Admit 按本地网关中间件链复查一个 API Key 请求（全局黑名单、Key 鉴权与计费检查、未分组拦截；
	// 分组模型白名单除外：从节点用回复里分组的白名单在本地跑同一个中间件），通过时回 Key 快照，
	// 从节点据此运行处理函数里选号之前的步骤。只读，不带幂等键；选号时主节点仍然独立复查。
	Admit(context.Context, *AdmitRequest) (*AdmitResponse, error)
	// ResolveRoute 按模型定这次请求的走向（本地 autoGroupModelRouting、compositeTarget 两个中间件，设计 3.2）：
	// 自动分组 Key 按模型选分组，组合平台分组按模型选目标平台和上游模型。准入之后、从节点读出请求体里的模型再调
	// （本地这两个中间件也在鉴权之后、读请求体时才做）。不带幂等键：自动分组的选组记在主节点（与本地同一个选组器），
	// 重发只会得到同一个或按同样规则的选择；组合平台选目标只读，选号时主节点按同样的输入再选一次。
	ResolveRoute(context.Context, *ResolveRouteRequest) (*ResolveRouteResponse, error)
	// SwitchAutoGroup 自动分组 Key 在一次请求里换到下一个候选分组（本地 tryOpenAIAutoGroupFailover）：当前分组选不出
	// 账号或换号用完时从节点调。主节点把当前分组记为失败，按同一个选组器选下一个这次请求没试过的候选。
	// 不幂等（会记失败、改选组状态）：超时不重发，按"没换"处理。
	SwitchAutoGroup(context.Context, *SwitchAutoGroupRequest) (*SwitchAutoGroupResponse, error)
	// ReportAutoGroupResult 自动分组 Key 一次请求的最终结果（本地自动分组中间件在请求结束时的观察）：主节点据此
	// 调整之后的选组（首字慢、失败时换组）。从节点在后台发，失败不重试。
	ReportAutoGroupResult(context.Context, *AutoGroupResult) (*AutoGroupResultAck, error)
	// SwitchFallbackGroup Antigravity 回 prompt 过长时换到分组配置的兜底分组（本地 Messages 里 PromptTooLongError 的分支）：
	// 主节点按本地同一套检查解析兜底分组（Anthropic 平台、非订阅、自己没有兜底）、做计费资格复查，回兜底分组的 Key 快照。
	// 之后的选号带 fallback_group_id。
	SwitchFallbackGroup(context.Context, *SwitchFallbackGroupRequest) (*SwitchFallbackGroupResponse, error)
	// UserMsgQueue 用户消息串行队列的一步（锁、上次完成时间、Redis 时钟、账号当前 RPM，都在主节点的 Redis）：从节点的
	// 处理函数照本地同一段排队代码（含排队期间的 SSE 保活），每一步在主节点执行。只认这台节点正在用的账号。
	UserMsgQueue(context.Context, *UserMsgQueueRequest) (*UserMsgQueueResponse, error)
	// Select 为一次客户端请求的一次尝试选号：主节点复查凭据、做只有它能做的检查、选号、占并发槽，
	// 签发扣费凭证，需要时顺带补充额度。带幂等键（请求 ID + 第几次选号）：超时重发拿到同一个结果。
	// 被拒绝时正常返回 rejection（不是 gRPC 错误），从节点按它写客户端响应。
	Select(context.Context, *SelectRequest) (*SelectResponse, error)
	// FetchCredentials 取一次进行中的选号所选账号的上游凭据：从节点缓存里没有这个版本时用（设计 9.1）。
	// 只有这次选号还没释放、且账号就是它选中的，主节点才给。
	FetchCredentials(context.Context, *FetchCredentialsRequest) (*FetchCredentialsResponse, error)
	// RefillQuota 按一次进行中的选号补充额度（提前补充，设计 4.2）：主节点按这次选号的用户、Key、
	// 分组、订阅重新算剩余；选号已释放时拒绝。
	RefillQuota(context.Context, *RefillQuotaRequest) (*RefillQuotaResponse, error)
	// UpstreamError 上游错误决策（设计 3.1 第 10 步）：从节点转发遇到上游错误时同步调用，主节点用
	// 单机同一段代码判定并记录账号状态（限流、临时不可调度、停用、冷却），返回判定结果。
	// 只能针对这台节点正在用的账号（有进行中的选号）。
	UpstreamError(context.Context, *UpstreamErrorRequest) (*UpstreamErrorResponse, error)
	// ---- Responses WebSocket（开发计划 WP10-3）----
	// BeginTurn 一条 WebSocket 连接的一轮开始时同步调用：按当时的利润门复核这次选号的账号、冻结这一轮的计价时间、
	// 补占这一轮的用户槽和账号槽（不排队）、按这一轮的模型签凭证，尽量补充额度（额度不够也不拒绝：单机只在建连时
	// 查计费资格）。复核不过或占不到槽时回 close，从节点按它关闭连接。
	BeginTurn(context.Context, *BeginTurnRequest) (*BeginTurnResponse, error)
	// TurnMapping 一轮的渠道映射（这一轮换了模型时，按模型缓存）。选号必须是这台节点进行中的。
	TurnMapping(context.Context, *TurnMappingRequest) (*TurnMappingResponse, error)
	// WebSocketLease 每个 Key 的 WebSocket 连接数租约（Redis 里的全局租约，主节点代为申请、续期、释放；
	// 上限用主节点的配置）。租约按节点记归属，别的节点不能续期或释放。
	WebSocketLease(context.Context, *WebSocketLeaseRequest) (*WebSocketLeaseResponse, error)
	// CyberPolicyHit 上游判定 cyber 策略后调用（设计 3.4）：主节点写会话屏蔽标记（同步，属于授权），用单机同一段
	// 代码（handler.CyberPolicyRecorder）；风控记录、运维日志由从节点写本机。用户、Key、分组、账号取自这次选号的
	// 记录，屏蔽的键由选号时上送的查询键推导；每次请求只记一次。选号必须是这台节点进行中的。
	CyberPolicyHit(context.Context, *CyberPolicyHitRequest) (*CyberPolicyHitResponse, error)
	// ---- 内容审核命中后的账号动作（设计 3.4）：判定和记录在从节点，违规次数跨节点累计、封号、邮件在主节点 ----
	// ModerationViolation 从节点写一条计入封号的审核记录之前调用：主节点用单机同一段代码累计窗口内违规次数、
	// 按阈值封号，并记一条不含输入内容的违规记录（带节点）。只认这台节点最近准入过的用户。带幂等键。
	ModerationViolation(context.Context, *ModerationViolationRequest) (*ModerationViolationResponse, error)
	// ModerationNotify 命中与封号通知邮件（SMTP 不下发，由主节点发）。收件人按主节点库里的用户。
	ModerationNotify(context.Context, *ModerationNotifyRequest) (*ModerationNotifyResponse, error)
	// FetchFlaggedHashes 分页拉取命中过的输入名单（从节点每次连上事件流后整份拉一次，之后按增量更新）。
	FetchFlaggedHashes(context.Context, *FetchFlaggedHashesRequest) (*FetchFlaggedHashesResponse, error)
	// RecordFlaggedHash 从节点新命中的输入：主节点写进名单，再把增量推给所有节点。
	RecordFlaggedHash(context.Context, *RecordFlaggedHashRequest) (*RecordFlaggedHashResponse, error)
	// ReportWebSearchUsage 联网搜索用量（设计 3.3）：搜索在从节点执行，各搜索服务的配额是全局的。从节点定期报
	// 上次确认以来新用的次数，主节点加进全局计数，回每个服务当前的上限、已用和这台可用的份额（剩余按在线节点分摊）。
	// 带幂等键：回复丢了重发同一份，只加一次。
	ReportWebSearchUsage(context.Context, *WebSearchUsageReport) (*WebSearchUsageShares, error)
	// 小白端转发接口（/paw/*）：从节点验过票据后，每个请求向主节点解析（设计 8.1）。主节点复查用户（存在、启用、token_version、
	// 后台模式），按本地 /paw 同一段服务代码（PawChatService / PawImageService）校验分组和模型、取内部 key 钉死在分组上，回一个
	// 不透明的会话句柄：之后这次请求的选号、换组等调用用它代替 API Key 原文，**内部 key 的原文不离开主节点**。
	PawResolve(context.Context, *PawResolveRequest) (*PawResolveResponse, error)
	mustEmbedUnimplementedRelayControlServer()
}

